/**
 * Canonical DM SITREP presentation model.
 * Consumes registered feature APIs only; never reads SITREP flags directly.
 */

const SITREP_TYPE_LABELS = Object.freeze({
  gauntlet: "Gauntlet",
  control: "Control",
  holdout: "Holdout",
  escort: "Escort",
  extraction: "Extraction",
  recon: "Recon"
});

const SITREP_TYPE_ORDER = Object.freeze([
  "gauntlet",
  "control",
  "holdout",
  "escort",
  "extraction",
  "recon"
]);

function optionFromDocument(document) {
  return Object.freeze({
    id: String(document?.id ?? ""),
    label: String(document?.name ?? document?.id ?? "Unnamed")
  });
}

function normalizedArray(value) {
  return Array.isArray(value) ? value : [];
}

function statusLabel(state, derivedState) {
  if (!state) return "NOT CONFIGURED";
  if (state.status === "victory") return "MISSION SUCCESS";
  if (state.status === "defeat") return "MISSION FAILED";
  if (state.status === "draw") return "NO VICTOR";
  if (state.status === "paused") return "SITREP PAUSED";
  if (Number(derivedState?.roundsRemaining) === 1) return "FINAL ROUND";
  return `${Math.max(Number(derivedState?.roundsRemaining ?? 0), 0)} ROUNDS REMAINING`;
}

export async function buildDmSitrepViewModel({
  sitrepsApi,
  foundryApi
} = {}) {
  if (!sitrepsApi || !foundryApi) {
    throw new Error("DM SITREP view model requires SITREP and Foundry APIs.");
  }

  const combat =
    foundryApi.getActiveCombat?.() ??
    null;

  const operationalRecord =
    sitrepsApi.operationalState?.(combat) ??
    {
      combat,
      source: "none",
      state: null,
      canonicalPresent: false
    };

  const state =
    operationalRecord?.state ??
    null;

  const derivedState =
    state
      ? await sitrepsApi.presentationState?.(combat)
      : null;

  const regions =
    normalizedArray(
      foundryApi.listCombatRegions?.(combat)
    ).map(optionFromDocument);

  const combatants =
    normalizedArray(
      foundryApi.listCombatants?.(combat)
    ).map(optionFromDocument);

  const type =
    String(
      state?.type ??
      "gauntlet"
    ).toLowerCase();

  return Object.freeze({
    hasCombat:
      Boolean(combat),

    combatId:
      combat?.id ??
      null,

    combatRound:
      Math.max(
        Number(combat?.round ?? 1),
        1
      ),

    source:
      operationalRecord?.source ??
      "none",

    state,

    derivedState,

    configured:
      Boolean(state),

    active:
      Boolean(
        state?.active &&
        state?.status !== "ended"
      ),

    statusLabel:
      statusLabel(
        state,
        derivedState
      ),

    type,

    typeLabel:
      SITREP_TYPE_LABELS[type] ??
      type.toUpperCase(),

    typeOptions:
      SITREP_TYPE_ORDER.map(id => ({
        id,
        label:
          SITREP_TYPE_LABELS[id]
      })),

    regions,

    combatants,

    selectedControlRegionIds:
      normalizedArray(
        state?.controlRegionIds
      ),

    selectedReconRegionIds:
      normalizedArray(
        state?.reconRegionIds
      ),

    selectedReconTrueRegionId:
      String(
        state?.reconTrueRegionId ??
        ""
      ),

    canManage:
      Boolean(
        foundryApi.isPrimaryGM?.()
      )
  });
}

/**
 * DM SITREP interaction adapter.
 * Converts DOM intent into canonical SITREP API commands.
 */

function selectedValues(select) {
  return Array.from(
    select?.selectedOptions ??
    []
  ).map(option => option.value);
}

function formRequest(form) {
  const elements =
    form?.elements;

  return {
    type:
      elements?.type?.value ??
      "gauntlet",

    title:
      elements?.title?.value ??
      "",

    objective:
      elements?.objective?.value ??
      "",

    roundLimit:
      Number(
        elements?.roundLimit?.value ??
        8
      ),

    regionId:
      elements?.regionId?.value ??
      "",

    controlRegionIds:
      selectedValues(
        elements?.controlRegionIds
      ),

    holdoutBaseScore:
      Number(
        elements?.holdoutBaseScore?.value ??
        4
      ),

    escortObjectiveCombatantId:
      elements
        ?.escortObjectiveCombatantId
        ?.value ??
      "",

    escortExtractionRegionId:
      elements
        ?.escortExtractionRegionId
        ?.value ??
      "",

    extractionObjectiveCombatantId:
      elements
        ?.extractionObjectiveCombatantId
        ?.value ??
      "",

    extractionZoneRegionId:
      elements
        ?.extractionZoneRegionId
        ?.value ??
      "",

    reconRegionIds:
      selectedValues(
        elements?.reconRegionIds
      ),

    reconTrueRegionId:
      elements
        ?.reconTrueRegionId
        ?.value ??
      "",

    rules: {
      finalZoneControl:
        Boolean(
          elements
            ?.finalZoneControl
            ?.checked
        ),

      enemyElimination:
        Boolean(
          elements
            ?.enemyElimination
            ?.checked
        ),

      unassailableControl:
        Boolean(
          elements
            ?.unassailableControl
            ?.checked
        )
    }
  };
}

const FIELD_TYPES =
  Object.freeze({
    "single-region":
      new Set([
        "gauntlet",
        "holdout"
      ]),

    "control-regions":
      new Set([
        "control"
      ]),

    "holdout-score":
      new Set([
        "holdout"
      ]),

    "escort-objective":
      new Set([
        "escort"
      ]),

    "escort-region":
      new Set([
        "escort"
      ]),

    "extraction-objective":
      new Set([
        "extraction"
      ]),

    "extraction-region":
      new Set([
        "extraction"
      ]),

    "recon-regions":
      new Set([
        "recon"
      ]),

    "recon-true":
      new Set([
        "recon"
      ])
  });

function synchronizeTypeFields(root) {
  const type =
    root
      .querySelector(
        "[data-dm-sitrep-type]"
      )
      ?.value ??
    "gauntlet";

  for (
    const field
    of root.querySelectorAll(
      "[data-sitrep-field]"
    )
  ) {
    const fieldId =
      field.dataset
        .sitrepField;

    field.hidden =
      !FIELD_TYPES[
        fieldId
      ]?.has(type);
  }

  root.dataset.sitrepType =
    type;
}

function showValidation(root, errors = []) {
  const target =
    root.querySelector(
      "[data-dm-sitrep-validation]"
    );

  if (!target) {
    return;
  }

  target.textContent =
    errors.join(" \

operations:
No active Combat is available."
    );
  }

  if (
    command === "configure" ||
    command === "start"
  ) {
    const form =
      application.element
        ?.find?.(
          "[data-dm-sitrep-form]"
        )?.[0] ??
      application.element?.[0]
        ?.querySelector?.(
          "[data-dm-sitrep-form]"
        ) ??
      null;

    const request =
      formRequest(form);

    const validation =
      sitrepsApi.validateSetup(
        request
      );

    if (!validation.valid) {
      showValidation(
        form,
        validation.errors
      );

      return;
    }

    if (command === "configure") {
      await sitrepsApi.configure(
        request,
        combat
      );
    } else {
      await sitrepsApi.start(
        request,
        combat
      );
    }

    application.showSetup =
      false;

    return;
  }

  if (command === "edit") {
    application.showSetup =
      true;

    return;
  }

  if (command === "toggle-pause") {
    await sitrepsApi.togglePause(
      combat
    );
    return;
  }

  if (command === "victory") {
    await sitrepsApi.setResult(
      "victory",
      "Victory declared by the GM.",
      combat
    );
    return;
  }

  if (command === "defeat") {
    await sitrepsApi.setResult(
      "defeat",
      "Defeat declared by the GM.",
      combat
    );
    return;
  }

  if (command === "end") {
    await sitrepsApi.end(
      combat
    );

    application.showSetup =
      true;

    return;
  }

  if (command === "recon-scan") {
    await sitrepsApi.scanReconRegion(
      combat,
      control.dataset.regionId
    );
    return;
  }

  if (command === "escort-extract") {
    await sitrepsApi.resolveEscortOutcome(
      combat,
      "extracted"
    );
    return;
  }

  if (command === "escort-destroy") {
    await sitrepsApi.resolveEscortOutcome(
      combat,
      "destroyed"
    );
    return;
  }

  if (command === "extraction-extract") {
    await sitrepsApi.resolveExtractionOutcome(
      combat,
      "extracted"
    );
    return;
  }

  if (command === "extraction-destroy") {
    await sitrepsApi.resolveExtractionOutcome(
      combat,
      "destroyed"
    );
  }
}

export function activateDmSitrepListeners(
  application,
  html,
  {
    sitrepsApi,
    foundryApi
  } = {}
) {
  const root =
    html?.[0] ??
    html;

  if (!root) {
    return;
  }

  synchronizeTypeFields(root);

  root
    .querySelector(
      "[data-dm-sitrep-type]"
    )
    ?.addEventListener(
      "change",
      () =>
        synchronizeTypeFields(root)
    );

  for (
    const control
    of root.querySelectorAll(
      "[data-dm-sitrep-command]"
    )
  ) {
    control.addEventListener(
      "click",
      async event => {
        event.preventDefault();

        control.disabled =
          true;

        try {
          await executeCommand({
            application,
            sitrepsApi,
            foundryApi,
            command:
              control.dataset
                .dmSitrepCommand,
            control
          });

          await application.render(
            true
          );
        } catch (error) {
          console.error(
            "Frame Conn | DM SITREP command failed.",
            error
          );

          ui.notifications.error(
            error?.message ??
            "SITREP command failed."
          );
        } finally {
          control.disabled =
            false;
        }
      }
    );
  }
}

