/**
 * styles/ui_dm/ui-dm-application.js
 *
 * Canonical GM-facing Frame Conn // Mission application.
 */

import {
  defineFrameConnFeature
} from "../../scripts/feature-contract.js";

import {
  buildDmSitrepViewModel
} from "./components/dm-sitrep-view-model.js";

import {
  renderDmSitrepApplication
} from "./components/dm-sitrep-presentation.js";

import {
  activateDmSitrepListeners
} from "./components/dm-sitrep-listeners.js";

const runtime = {
  sitrepsApi: null,
  foundryApi: null
};

let dmApplication =
  null;

function configureFrameConnDmApplicationRuntime({
  sitrepsApi,
  foundryApi
} = {}) {
  if (sitrepsApi !== undefined) {
    runtime.sitrepsApi =
      sitrepsApi;
  }

  if (foundryApi !== undefined) {
    runtime.foundryApi =
      foundryApi;
  }

  return getFrameConnDmApplicationRuntimeBindings();
}

function getFrameConnDmApplicationRuntimeBindings() {
  return Object.freeze({
    sitreps:
      Boolean(runtime.sitrepsApi),

    foundry:
      Boolean(runtime.foundryApi)
  });
}

function assertRuntime() {
  if (
    !runtime.sitrepsApi ||
    !runtime.foundryApi
  ) {
    throw new Error(
      "Frame Conn DM Application runtime has not been configured."
    );
  }
}

export class FrameConnDmApplication
  extends Application {

  static get defaultOptions() {
    return foundry.utils.mergeObject(
      super.defaultOptions,
      {
        id:
          "lancer-frame-conn-dm",

        title:
          "Frame Conn // Mission",

        classes: [
          "lancer-frame-conn-dm"
        ],

        width:
          760,

        height:
          720,

        resizable:
          true,

        minimizable:
          true
      }
    );
  }

  constructor(options = {}) {
    super(options);

    this.showSetup =
      false;
  }

  async getData() {
    assertRuntime();

    const model =
      await buildDmSitrepViewModel({
        sitrepsApi:
          runtime.sitrepsApi,

        foundryApi:
          runtime.foundryApi
      });

    if (!model.configured) {
      this.showSetup =
        true;
    }

    return {
      model
    };
  }

  async _renderInner(data) {
    const wrapper =
      document.createElement(
        "div"
      );

    wrapper.innerHTML =
      renderDmSitrepApplication(
        data.model,
        {
          showSetup:
            this.showSetup
        }
      );

    return $(
      wrapper.firstElementChild
    );
  }

  activateListeners(html) {
    super.activateListeners(
      html
    );

    activateDmSitrepListeners(
      this,
      html,
      {
        sitrepsApi:
          runtime.sitrepsApi,

        foundryApi:
          runtime.foundryApi
      }
    );
  }
}

export function getFrameConnDmApplication() {
  dmApplication ??=
    new FrameConnDmApplication();

  return dmApplication;
}

export function openFrameConnDmApplication() {
  assertRuntime();

  if (
    !runtime.foundryApi
      .isPrimaryGM?.()
  ) {
    ui.notifications.warn(
      "Frame Conn // Mission is available to the active GM."
    );

    return null;
  }

  const application =
    getFrameConnDmApplication();

  application.render(
    true
  );

  return application;
}

export async function closeFrameConnDmApplication() {
  if (!dmApplication) {
    return null;
  }

  return dmApplication.close();
}

export function renderFrameConnDmApplication(
  force = true
) {
  if (
    !dmApplication?.rendered
  ) {
    return null;
  }

  return dmApplication.render(
    force
  );
}

function handleDmApplicationCombatChange() {
  return renderFrameConnDmApplication(
    true
  );
}

export const frameConnDmApplicationUiFeature =
  defineFrameConnFeature({
    id:
      "ui-dm-application",

    domain:
      "ui.dm",

    provides: [
      "ui.dm",
      "ui.dm.application",
      "ui.dm.sitrep-presentation"
    ],

    dependsOn: [
      "dm.sitreps",
      "foundry.integration"
    ],

    optionalDependsOn: [],

    state: {},

    commands: {
      configureRuntime:
        configureFrameConnDmApplicationRuntime,

      open:
        openFrameConnDmApplication,

      close:
        closeFrameConnDmApplication,

      render:
        renderFrameConnDmApplication
    },

    queries: {
      getApplication:
        getFrameConnDmApplication,

      runtimeBindings:
        getFrameConnDmApplicationRuntimeBindings
    },

    hooks: {
      updateCombat:
        handleDmApplicationCombatChange,

      createCombat:
        handleDmApplicationCombatChange,

      deleteCombat:
        handleDmApplicationCombatChange
    },

    lifecycle: {},

    api: {
      configureRuntime:
        configureFrameConnDmApplicationRuntime,

      open:
        openFrameConnDmApplication,

      close:
        closeFrameConnDmApplication,

      render:
        renderFrameConnDmApplication,

      getApplication:
        getFrameConnDmApplication,

      runtimeBindings:
        getFrameConnDmApplicationRuntimeBindings
    },

    metadata: {
      audience:
        "gm",

      label:
        "Frame Conn // Mission",

      companionStylesheet:
        "styles/ui_dm/ui-dm-application.css",

      phase:
        "sitrep-assimilation-phase-6"
    }
  });

/* Frame Conn // Mission — separate GM-facing mission-control surface. */

