  --fc-dm-cyan: var(--fc-cyan, #5be0d9);
  --fc-dm-muted: rgba(216, 247, 243, 0.64);
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  gap: 0.8rem;
  padding: 0.9rem;
  overflow-y: auto;
  background:
    repeating-linear-gradient(
      0deg,
      rgba(255,255,255,0.018) 0,
      rgba(255,255,255,0.018) 1px,
      transparent 1px,
      transparent 4px
