import {
  FRAME_CONN_SITREP_FEATURES
} from "./sitreps/sitreps-feature-package.js";

import {
  frameConnDmApplicationUiFeature
} from "../../styles/ui_dm/ui-dm-application.js";

export const FRAME_CONN_DM_FEATURES =
  Object.freeze([
    ...FRAME_CONN_SITREP_FEATURES,
    frameConnDmApplicationUiFeature
  ]);

/** Canonical Escort objective/result transitions. No chat, DOM, or hook ownership. */

import {
  readSitrepState,
  updateSitrepState
} from "../state/sitrep-state-service.js";

import {
  calculateEscortState
} from "./escort-state.js";

function outcomeIntent(
  status,
  reason,
  event
) {
  return Object.freeze({
    kind:
      "sitrep-objective-result",

    sitrepType:
      "escort",

    event,
    status,
    reason
  });
}

export async function resolveEscortObjective(
  combat,
  outcome,
  spatialOperations
) {
  const sitrep =
    readSitrepState(combat);

  if (
    !combat ||
    !sitrep ||
    sitrep.type !== "escort"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null,
      rejection: "not-escort"
    });
  }

  const state =
    await calculateEscortState(
      combat,
      sitrep,
      spatialOperations
    );

  if (!state.valid) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      derivedState: state,
      outputIntent: null,
      rejection:
        "invalid-objective-configuration"
    });
  }

  if (outcome === "extracted") {
    const reason =
      "The Objective was safely extracted.";

    const nextState =
      await updateSitrepState(
        {
          escortStatus:
            "extracted",

          status:
            "victory",

          resultReason:
            reason
        },
        combat
      );

    return Object.freeze({
      changed: true,
      state: nextState,
      derivedState: state,
      outputIntent:
        outcomeIntent(
          "victory",
          reason,
          "extracted"
        ),
      rejection: null
    });
  }

  if (outcome === "destroyed") {
    const reason =
      "The Objective was destroyed. Neither side achieved victory.";

    const nextState =
      await updateSitrepState(
        {
          escortStatus:
            "destroyed",

          status:
            "draw",

          resultReason:
            reason
        },
        combat
      );

    return Object.freeze({
      changed: true,
      state: nextState,
      derivedState: state,
      outputIntent:
        outcomeIntent(
          "draw",
          reason,
          "destroyed"
        ),
      rejection: null
    });
  }

  return Object.freeze({
    changed: false,
    state: sitrep,
    derivedState: state,
    outputIntent: null,
    rejection:
      "unknown-outcome"
  });
}

export async function resolveEscortEncounterUpdate(
  combat,
  changes = {},
  spatialOperations
) {
  const sitrep =
    readSitrepState(combat);

  if (
    !combat ||
    !sitrep ||
    sitrep.type !== "escort" ||
    !sitrep.active ||
    sitrep.status !== "active"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  const state =
    await calculateEscortState(
      combat,
      sitrep,
      spatialOperations
    );

  if (!state.valid) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  if (
    state.objectiveDestroyed &&
    sitrep.escortStatus !==
      "destroyed"
  ) {
    return resolveEscortObjective(
      combat,
      "destroyed",
      spatialOperations
    );
  }

  if (state.canExtractObjective) {
    return resolveEscortObjective(
      combat,
      "extracted",
      spatialOperations
    );
  }

  if (
    Object.prototype
      .hasOwnProperty.call(
        changes ?? {},
        "round"
      ) &&
    Number(changes.round) >
      Number(sitrep.finalRound)
  ) {
    const reason =
      `The Objective was not extracted by the end of round ${sitrep.finalRound}.`;

    const nextState =
      await updateSitrepState(
        {
          status:
            "defeat",

          resultReason:
            reason
        },
        combat
      );

    return Object.freeze({
      changed: true,
      state: nextState,
      derivedState: state,
      outputIntent:
        outcomeIntent(
          "defeat",
          reason,
          "round-limit"
        )
    });
  }

  return Object.freeze({
    changed: false,
    state: sitrep,
    derivedState: state,
    outputIntent: null
  });
}

/**
 * Canonical SITREP application orchestration.
 * Runtime composition is supplied by the authoritative Frame Conn orchestrator.
 */

import {
  clearSitrepState,
  readSitrepState,
  readSitrepStateRecord,
  updateSitrepState,
  writeSitrepState
} from "../state/sitrep-state-service.js";

import {
  calculateGauntletState
} from "../gauntlet/gauntlet-state.js";

import {
  resolveGauntletEncounterUpdate
} from "../gauntlet/gauntlet-resolution.js";

import {
  calculateControlState
} from "../control/control-state.js";

import {
  resolveControlEncounterUpdate
} from "../control/control-resolution.js";

import {
  calculateHoldoutState
} from "../holdout/holdout-state.js";

import {
  resolveHoldoutEncounterUpdate
} from "../holdout/holdout-resolution.js";

import {
  calculateEscortState
} from "../escort/escort-state.js";

import {
  resolveEscortEncounterUpdate,
  resolveEscortObjective
} from "../escort/escort-resolution.js";

import {
  calculateExtractionState
} from "../extraction/extraction-state.js";

import {
  resolveExtractionEncounterUpdate,
  resolveExtractionObjective
} from "../extraction/extraction-resolution.js";

import {
  calculateReconState
} from "../recon/recon-state.js";

import {
  recordReconScan,
  resolveReconEncounterUpdate
} from "../recon/recon-resolution.js";

import {
  buildConfiguredSitrepState,
  validateSitrepSetup
} from "./sitrep-setup.js";

const runtime = {
  spatialOperations:
    null,

  publishOutputIntent:
    null,

  canManageSitreps:
    () =>
      Boolean(
        globalThis.game
          ?.user
          ?.isGM
      )
};

export function configureSitrepOrchestrationRuntime({
  spatialOperations,
  publishOutputIntent,
  canManageSitreps
} = {}) {
  if (spatialOperations !== undefined) {
    runtime.spatialOperations =
      spatialOperations;
  }

  if (publishOutputIntent !== undefined) {
    if (
      typeof publishOutputIntent !==
      "function"
    ) {
      throw new TypeError(
        "SITREP output publisher must be a function."
      );
    }

    runtime.publishOutputIntent =
      publishOutputIntent;
  }

  if (canManageSitreps !== undefined) {
    if (
      typeof canManageSitreps !==
      "function"
    ) {
      throw new TypeError(
        "SITREP authorization binding must be a function."
      );
    }

    runtime.canManageSitreps =
      canManageSitreps;
  }

  return getSitrepOrchestrationDiagnostics();
}

function assertManagePermission() {
  if (!runtime.canManageSitreps()) {
    throw new Error(
      "Only an authorized GM may manage SITREPs."
    );
  }
}

function requireSpatialOperations() {
  if (!runtime.spatialOperations) {
    throw new Error(
      "SITREP spatial operations have not been configured."
    );
  }

  return runtime.spatialOperations;
}

async function publishOutputIntent(
  intent
) {
  if (!intent) {
    return null;
  }

  if (
    typeof runtime
      .publishOutputIntent !==
    "function"
  ) {
    throw new Error(
      "SITREP semantic output publishing has not been configured."
    );
  }

  return runtime.publishOutputIntent(
    intent
  );
}

async function publishResultIntents(
  result
) {
  if (!result) {
    return result;
  }

  const intents =
    Array.isArray(
      result.outputIntents
    )
      ? result.outputIntents
      : result.outputIntent
        ? [result.outputIntent]
        : [];

  for (const intent of intents) {
    await publishOutputIntent(
      intent
    );
  }

  return result;
}

export function getSitrepOperationalState(
  combat = null
) {
  return readSitrepStateRecord(
    combat
  );
}

const presentationStateCalculators =
  Object.freeze({
    gauntlet:
      calculateGauntletState,

    control:
      calculateControlState,

    holdout:
      calculateHoldoutState,

    escort:
      calculateEscortState,

    extraction:
      calculateExtractionState,

    recon:
      calculateReconState
  });

export async function getSitrepPresentationState(
  combat = null
) {
  const sitrep =
    readSitrepState(combat);

  if (!sitrep) {
    return null;
  }

  const calculator =
    presentationStateCalculators[
      sitrep.type
    ];

  if (!calculator) {
    return null;
  }

  return calculator(
    readSitrepStateRecord(combat)
      .combat,
    sitrep,
    requireSpatialOperations()
  );
}

export function getSitrepOrchestrationDiagnostics() {
  return Object.freeze({
    spatialConfigured:
      Boolean(
        runtime.spatialOperations
      ),

    outputPublisherConfigured:
      typeof runtime
        .publishOutputIntent ===
      "function",

    authorizationConfigured:
      typeof runtime
        .canManageSitreps ===
      "function"
  });
}

export async function configureSitrep(
  request,
  combat = null
) {
  assertManagePermission();

  const existing =
    readSitrepState(combat);

  return writeSitrepState(
    buildConfiguredSitrepState(
      request,
      combat,
      existing,
      {
        resetProgress:
          false
      }
    ),
    combat
  );
}

export async function startSitrep(
  request,
  combat = null
) {
  assertManagePermission();

  const existing =
    readSitrepState(combat);

  const state =
    await writeSitrepState(
      buildConfiguredSitrepState(
        request,
        combat,
        existing,
        {
          resetProgress:
            true
        }
      ),
      combat
    );

  await publishOutputIntent(
    Object.freeze({
      kind:
        "sitrep-started",

      sitrepType:
        state.type,

      title:
        state.title,

      finalRound:
        state.finalRound
    })
  );

  return state;
}

export async function toggleSitrepPause(
  combat = null
) {
  assertManagePermission();

  const sitrep =
    readSitrepState(combat);

  if (!sitrep) {
    throw new Error(
      "Cannot pause or resume because no SITREP is configured."
    );
  }

  return updateSitrepState(
    {
      status:
        sitrep.status === "paused"
          ? "active"
          : "paused"
    },
    combat
  );
}

export async function endSitrep(
  combat = null
) {
  assertManagePermission();

  await clearSitrepState(
    combat
  );

  await publishOutputIntent(
    Object.freeze({
      kind:
        "sitrep-ended"
    })
  );

  return null;
}

export async function setSitrepResult(
  status,
  reason,
  combat = null
) {
  assertManagePermission();

  const normalizedStatus =
    String(status ?? "")
      .trim()
      .toLowerCase();

  if (
    ![
      "victory",
      "defeat",
      "draw"
    ].includes(
      normalizedStatus
    )
  ) {
    throw new Error(
      `Unsupported SITREP result status: ${normalizedStatus}.`
    );
  }

  const resultReason =
    String(reason ?? "")
      .trim();

  const state =
    await updateSitrepState(
      {
        status:
          normalizedStatus,

        resultReason
      },
      combat
    );

  const outputIntent =
    Object.freeze({
      kind:
        "sitrep-result",

      sitrepType:
        state.type,

      status:
        normalizedStatus,

      reason:
        resultReason
    });

  await publishOutputIntent(
    outputIntent
  );

  return Object.freeze({
    changed: true,
    state,
    outputIntent
  });
}

const encounterResolvers =
  Object.freeze({
    gauntlet:
      resolveGauntletEncounterUpdate,

    control:
      resolveControlEncounterUpdate,

    holdout:
      resolveHoldoutEncounterUpdate,

    escort:
      resolveEscortEncounterUpdate,

    extraction:
      resolveExtractionEncounterUpdate,

    recon:
      resolveReconEncounterUpdate
  });

export async function evaluateSitrepCombatChange(
  combat,
  changes = {}
) {
  if (!runtime.canManageSitreps()) {
    return Object.freeze({
      changed: false,
      state:
        readSitrepState(combat),
      outputIntent: null
    });
  }

  const sitrep =
    readSitrepState(combat);

  if (
    !sitrep?.active ||
    sitrep.status !==
      "active"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  const resolver =
    encounterResolvers[
      sitrep.type
    ];

  if (!resolver) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  return publishResultIntents(
    await resolver(
      combat,
      changes,
      requireSpatialOperations()
    )
  );
}

export async function handleSitrepCombatUpdate(
  combat,
  changes = {}
) {
  try {
    return await evaluateSitrepCombatChange(
      combat,
      changes
    );
  } catch (error) {
    console.error(
      "Frame Conn | SITREP combat evaluation failed.",
      error
    );

    return Object.freeze({
      changed: false,
      state:
        readSitrepState(combat),
      outputIntent: null,
      error
    });
  }
}

export async function scanReconRegion(
  combat,
  regionId
) {
  assertManagePermission();

  return publishResultIntents(
    await recordReconScan(
      combat,
      regionId,
      requireSpatialOperations()
    )
  );
}

export async function resolveEscortOutcome(
  combat,
  outcome
) {
  assertManagePermission();

  return publishResultIntents(
    await resolveEscortObjective(
      combat,
      outcome,
      requireSpatialOperations()
    )
  );
}

export async function resolveExtractionOutcome(
  combat,
  outcome
) {
  assertManagePermission();

  return publishResultIntents(
    await resolveExtractionObjective(
      combat,
      outcome,
      requireSpatialOperations()
    )
  );
}

export {
  validateSitrepSetup
};

