      controls
    );

    return false;
  }

  let changed =
    insertFrameConnSceneControlTool(
      tokenControls
    );

  if (
    game?.user?.isGM &&
    typeof frameConnFoundryIntegrationRuntimeBindings
      .openDmApplication ===
      "function"
  ) {
    const dmTool =
      createFrameConnDmSceneControlTool(
        tokenControls
      );

    const tools =
      tokenControls.tools;

    const alreadyPresent =
      Array.isArray(tools)
        ? tools.some(
            tool =>
              tool?.name ===
              FRAME_CONN_DM_SCENE_CONTROL_NAME
          )
        : Boolean(
            tools?.[
              FRAME_CONN_DM_SCENE_CONTROL_NAME
            ]
          );

    if (!alreadyPresent) {
      if (Array.isArray(tools)) {
        tools.push(dmTool);
      } else {
        tokenControls.tools ??=
          {};

        tokenControls.tools[
          FRAME_CONN_DM_SCENE_CONTROL_NAME
        ] = dmTool;
      }

      changed =
        true;
    }
  }

  return changed;
}

